```typescript
import { describe, it, expect } from 'vitest'
import { parseSummaryJson, QuickSummary } from './summaryParser'

describe('parseSummaryJson', () => {
  it('parses valid JSON summary', () => {
    const json = JSON.stringify({
      tldr: 'Test summary.',
      keyTerms: [{ term: 'Term1', definition: 'Def1' }],
      argumentStructure: ['Step 1', 'Step 2'],
      modernApplication: 'Modern connection.',
      sourcePointers: {
        keyPassage: 'Quote here',
        bestExample: 'Example here',
        strongestArgument: 'Argument here',
      },
    })

    const result = parseSummaryJson(json)
    expect(result).not.toBeNull()
    expect(result?.tldr).toBe('Test summary.')
    expect(result?.keyTerms).toHaveLength(1)
  })

  it('extracts JSON from markdown code blocks', () => {
    const wrapped = '```json\n{"tldr": "Test", "keyTerms": [], "argumentStructure": [], "modernApplication": "", "sourcePointers": {"keyPassage": "", "bestExample": "", "strongestArgument": ""}}\n```'
    const result = parseSummaryJson(wrapped)
    expect(result?.tldr).toBe('Test')
  })

  it('returns null for invalid JSON', () => {
    const result = parseSummaryJson('not json')
    expect(result).toBeNull()
  })

  it('returns null for missing required fields', () => {
    const result = parseSummaryJson('{"tldr": "Only tldr"}')
    expect(result).toBeNull()
  })
})
```

**Step 2: Run test to verify it fails**

Run: `npm run test:run -- src/lib/prompts/summaryParser.test.ts`
Expected: FAIL with "Cannot find module './summaryParser'"

**Step 3: Write the implementation**

Create `src/lib/prompts/summaryParser.ts`:

```typescript
import { z } from 'zod'

// Zod schemas for robust validation
const KeyTermSchema = z.object({
  term: z.string().min(1),
  definition: z.string().min(1),
})

const SourcePointersSchema = z.object({
  keyPassage: z.string(),
  bestExample: z.string(),
  strongestArgument: z.string(),
})

const QuickSummarySchema = z.object({
  tldr: z.string().min(1),
  keyTerms: z.array(KeyTermSchema).min(1),
  argumentStructure: z.array(z.string()).min(1),
  modernApplication: z.string(),
  sourcePointers: SourcePointersSchema,
})

// Export types inferred from schemas
export type KeyTerm = z.infer<typeof KeyTermSchema>
export type SourcePointers = z.infer<typeof SourcePointersSchema>
export type QuickSummary = z.infer<typeof QuickSummarySchema>

/**
 * Parse JSON summary from AI output using zod validation.
 * Handles both raw JSON and markdown-wrapped JSON (```json ... ```)
 *
 * Uses zod instead of manual validation because:
 * - Validates nested structures (keyTerms items, sourcePointers keys)
 * - Provides better error messages for debugging
 * - Type-safe inference
 */
export function parseSummaryJson(input: string): QuickSummary | null {
  try {
    // Extract JSON from markdown code block if present
    const jsonMatch = input.match(/```json\s*([\s\S]*?)\s*```/)
    const jsonStr = jsonMatch ? jsonMatch[1] : input.trim()

    const parsed = JSON.parse(jsonStr)

    // Validate with zod schema
    const result = QuickSummarySchema.safeParse(parsed)

    if (!result.success) {
      console.warn('[SummaryParser] Validation failed:', result.error.issues)
      return null
    }

    return result.data
  } catch (err) {
    console.warn('[SummaryParser] JSON parse failed:', err)
    return null
  }
}

/**
 * Check if summary content is JSON format (new) or markdown (legacy)
 */
export function isJsonSummary(content: string): boolean {
  const trimmed = content.trim()
  return trimmed.startsWith('{') || trimmed.startsWith('```json')
}
```

