## Task 5: Create Detailed Summary Streaming Endpoint

**Files:**
- Create: `src/app/api/section/[id]/detailed/stream/route.ts`

**Step 1: Create the endpoint**

Create `src/app/api/section/[id]/detailed/stream/route.ts`:

```typescript
import { prisma } from '@/lib/db'
import { loadPrompt } from '@/lib/prompts/registry'
import { generateText } from '@/lib/ai/azure'

interface StreamEvent {
  paragraph?: number
  text?: string
  total?: number
  done?: boolean
  cached?: boolean
  locked?: boolean  // Another client is already generating
  error?: string
}

function createSSEStream(signal: AbortSignal) {
  const encoder = new TextEncoder()
  let controller: ReadableStreamDefaultController<Uint8Array>
  let isClosed = false

  const stream = new ReadableStream<Uint8Array>({
    start(c) {
      controller = c
    },
    cancel() {
      isClosed = true
    },
  })

  // Close stream if client disconnects
  signal.addEventListener('abort', () => {
    isClosed = true
    try { controller.close() } catch { /* already closed */ }
  })

  function send(event: StreamEvent) {
    if (isClosed) return false  // Client disconnected
    const data = `data: ${JSON.stringify(event)}\n\n`
    controller.enqueue(encoder.encode(data))
    return true
  }

  function close() {
    if (!isClosed) {
      isClosed = true
      controller.close()
    }
  }

  function isAborted() {
    return isClosed || signal.aborted
  }

  return { stream, send, close, isAborted }
}

/**
 * POST /api/section/[id]/detailed/stream
 * Generate and stream condensed detailed summary paragraph by paragraph
 *
 * Uses POST (not GET) because:
 * - Triggers expensive AI generation (non-idempotent)
 * - GET could be cached/pre-fetched by intermediaries
 */
export async function POST(req: Request, { params }: { params: { id: string } }) {
  const { stream, send, close, isAborted } = createSSEStream(req.signal)

  ;(async () => {
    const condensedParagraphs: string[] = []

    try {
      // Load section
      const section = await prisma.section.findUnique({
        where: { id: params.id },
        select: {
          sectionContent: true,
          detailedSummaryContent: true,
          book: { select: { title: true, author: true } },
        },
      })

      if (!section || !section.sectionContent) {
        send({ error: 'Section not found or has no content' })
        close()
        return
      }

      // Check cache first
      if (section.detailedSummaryContent) {
        send({ cached: true, text: section.detailedSummaryContent, done: true })
        close()
        return
      }

      // Generation lock: Atomic update to prevent race conditions
      // Only proceeds if detailedSummaryContent is still null
      const lockResult = await prisma.section.updateMany({
        where: {
          id: params.id,
          detailedSummaryContent: null  // Only lock if not already generating/cached
        },
        data: {
          detailedSummaryContent: '__GENERATING__'  // Lock marker
        },
      })

      if (lockResult.count === 0) {
        // Another client is already generating, or cache was just populated
        const recheckSection = await prisma.section.findUnique({
          where: { id: params.id },
          select: { detailedSummaryContent: true },
        })

        if (recheckSection?.detailedSummaryContent === '__GENERATING__') {
          send({ locked: true, error: 'Generation already in progress' })
        } else if (recheckSection?.detailedSummaryContent) {
          send({ cached: true, text: recheckSection.detailedSummaryContent, done: true })
        }
        close()
        return
      }

      // Split into paragraphs
      const paragraphs = section.sectionContent
        .split(/\r?\n\r?\n+/)
        .map((p) => p.trim())
        .filter((p) => p.length > 0)

      send({ total: paragraphs.length })

      // Load prompt
      const promptConfig = loadPrompt('condense_paragraph')

      // Process each paragraph
      for (let i = 0; i < paragraphs.length; i++) {
        // Check if client disconnected - stop generating to save tokens
        if (isAborted()) {
          console.log(`[Detailed] Client disconnected at paragraph ${i}/${paragraphs.length}, stopping generation`)
          // Clear lock marker since we didn't finish
          await prisma.section.update({
            where: { id: params.id },
            data: { detailedSummaryContent: null },
          })
          return
        }

        const paragraph = paragraphs[i]

        const prompt = promptConfig.template
          .replaceAll('{book_title}', section.book?.title ?? 'Unknown')
          .replaceAll('{author}', section.book?.author ?? 'Unknown')
          .replaceAll('{paragraph}', paragraph)

        const condensed = await generateText({
          prompt,
          maxTokens: 1024,
          temperature: 0.3,
        })

        condensedParagraphs.push(condensed.trim())

        // Send might return false if client disconnected
        if (!send({ paragraph: i, text: condensed.trim() })) {
          console.log(`[Detailed] Failed to send paragraph ${i}, client may have disconnected`)
        }
      }

      // Save to cache (replace lock marker with real content)
      const fullContent = condensedParagraphs.join('\n\n')

      await prisma.section.update({
        where: { id: params.id },
        data: { detailedSummaryContent: fullContent },
      })

      send({ done: true })
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Generation failed'
      send({ error: message })

      // Clear lock marker on error
      await prisma.section.update({
        where: { id: params.id },
        data: { detailedSummaryContent: null },
      }).catch(() => { /* ignore cleanup errors */ })
    } finally {
      close()
    }
  })()

  return new Response(stream, {
    headers: {
      'Content-Type': 'text/event-stream',
      'Cache-Control': 'no-store',  // Prevent caching of this mutable endpoint
      Connection: 'keep-alive',
    },
  })
}
```

