/**
 * Azure AI Foundry client for Claude models
 *
 * Uses Azure's Anthropic endpoint which follows Anthropic's Messages API format.
 */

type GenerateInput = {
  prompt: string
  model?: string
  maxTokens?: number
  temperature?: number
}

interface AnthropicMessage {
  role: 'user' | 'assistant'
  content: string
}

interface AnthropicResponse {
  content: Array<{ type: 'text'; text: string }>
  model: string
  stop_reason: string
  usage: {
    input_tokens: number
    output_tokens: number
  }
}

export async function generateText({
  prompt,
  model = process.env.AZURE_AI_MODEL ?? 'claude-sonnet-4-20250514',
  maxTokens = 8192,
  temperature = 0.3,
}: GenerateInput): Promise<string> {
  // Mock mode for testing without API calls
  if (process.env.MOCK_AI === 'true') {
    console.log('[AI] Mock mode enabled, returning placeholder')
    return 'MOCK_OUTPUT: This is placeholder content. Set MOCK_AI=false and configure Azure credentials to enable real AI generation.'
  }

  const endpoint = process.env.AZURE_AI_ENDPOINT
  const apiKey = process.env.AZURE_AI_KEY

  if (!endpoint || !apiKey) {
    throw new Error(
      'Azure AI not configured. Set AZURE_AI_ENDPOINT and AZURE_AI_KEY environment variables.'
    )
  }

  // Azure AI Foundry Anthropic endpoint uses /v1/messages path
  const url = `${endpoint}/v1/messages`

  const messages: AnthropicMessage[] = [{ role: 'user', content: prompt }]

  const body = {
    model,
    max_tokens: maxTokens,
    temperature,
    messages,
  }

  console.log(`[AI] Calling Azure AI Foundry: model=${model}, prompt length=${prompt.length}`)

  const response = await fetch(url, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'x-api-key': apiKey,
      'anthropic-version': '2023-06-01',
    },
    body: JSON.stringify(body),
  })

  if (!response.ok) {
    const errorText = await response.text()
    console.error(`[AI] Azure AI error: ${response.status} ${errorText}`)
    throw new Error(`Azure AI request failed: ${response.status} - ${errorText}`)
  }

  const data = (await response.json()) as AnthropicResponse

  console.log(
    `[AI] Response received: ${data.usage?.input_tokens ?? '?'} input, ${data.usage?.output_tokens ?? '?'} output tokens`
  )

  // Extract text from response
  const text = data.content
    .filter((block) => block.type === 'text')
    .map((block) => block.text)
    .join('\n')

  return text
}

