   446→  async function handleSimplifiedClick() {
   447→    if (readView === 'simplified') {
   448→      setReadView('original')
   449→      return
   450→    }
   451→
   452→    // Close any existing stream before starting new one
   453→    if (eventSourceRef.current) {
   454→      eventSourceRef.current.close()
   455→      eventSourceRef.current = null
   456→    }
   457→
   458→    setReadView('simplified')
   459→    setSimplifyError(null)
   460→    setSimplifiedContent('') // Clear stale content
   461→
   462→    // Re-fetch reading level to get latest preference
   463→    let currentLevel = readingLevel
   464→    try {
   465→      const prefRes = await fetch('/api/user/preferences')
   466→      const prefJson = await prefRes.json()
   467→      if (prefJson.success) {
   468→        currentLevel = prefJson.data.readingLevel
   469→        setReadingLevel(currentLevel)
   470→      }
   471→    } catch (err) {
   472→      console.error('Failed to fetch reading level:', err)
   473→    }
   474→
   475→    // Check server cache first
   476→    try {
   477→      const cacheRes = await fetch(`/api/section/${sectionId}/simplified?level=${currentLevel}`)
   478→      const cacheJson = await cacheRes.json()
   479→
   480→      if (cacheJson.success && cacheJson.data.cached) {
   481→        setSimplifiedContent(cacheJson.data.content)
   482→        setSimplifyStatus('ready')
   483→        // Clear any partial progress from localStorage
   484→        localStorage.removeItem(getProgressKey(currentLevel))
   485→        return
   486→      }
   487→    } catch (err) {
   488→      console.error('Cache check failed:', err)
   489→    }
   490→
   491→    // Check localStorage for partial progress (from previous interrupted session)
   492→    const progressKey = getProgressKey(currentLevel)
   493→    try {
   494→      const savedProgress = localStorage.getItem(progressKey)
   495→      if (savedProgress) {
   496→        const { paragraphs, total } = JSON.parse(savedProgress)
   497→        if (paragraphs && paragraphs.length > 0) {
   498→          setSimplifiedParagraphs(paragraphs)
   499→          setTotalParagraphs(total)
   500→          setSimplifyStatus('loading')
   501→          // Continue streaming from where we left off (server may have finished)
   502→        }
   503→      }
   504→    } catch (err) {
   505→      console.error('Failed to load progress from localStorage:', err)
   506→    }
   507→
   508→    // Stream generation
   509→    setSimplifyStatus('loading')
   510→    if (!simplifiedParagraphs.length) {
   511→      setSimplifiedParagraphs([])
   512→      setTotalParagraphs(0)
   513→    }
   514→
   515→    try {
   516→      const eventSource = new EventSource(
   517→        `/api/section/${sectionId}/simplified/stream?level=${currentLevel}`
   518→      )
   519→      eventSourceRef.current = eventSource
   520→
   521→      eventSource.onmessage = (event) => {
   522→        const data = JSON.parse(event.data)
   523→
   524→        if (data.error) {
   525→          setSimplifyError(data.error)
   526→          setSimplifyStatus('error')
   527→          eventSource.close()
   528→          eventSourceRef.current = null
   529→          return
   530→        }
   531→
   532→        if (data.total !== undefined) {
   533→          setTotalParagraphs(data.total)
   534→          // Save total to localStorage immediately
   535→          try {
   536→            const existing = localStorage.getItem(progressKey)
   537→            const parsed = existing ? JSON.parse(existing) : { paragraphs: [] }
   538→            localStorage.setItem(progressKey, JSON.stringify({ ...parsed, total: data.total }))
   539→          } catch (e) {
   540→            // ignore
   541→          }
   542→        }
   543→
   544→        if (data.paragraph !== undefined && data.text) {
   545→          setSimplifiedParagraphs((prev) => {
   546→            const updated = [...prev]
   547→            updated[data.paragraph] = data.text
   548→            // Save progress to localStorage
   549→            try {
   550→              const existing = localStorage.getItem(progressKey)
   551→              const existingTotal = existing ? JSON.parse(existing).total : updated.length
   552→              localStorage.setItem(progressKey, JSON.stringify({
   553→                paragraphs: updated,
   554→                total: existingTotal
   555→              }))
   556→            } catch (e) {
   557→              // localStorage might be full, ignore
   558→            }
   559→            return updated
   560→          })
   561→        }
   562→
   563→        if (data.done) {
   564→          setSimplifyStatus('ready')
   565→          // Clear localStorage - server has cached the complete content
   566→          localStorage.removeItem(progressKey)
   567→          eventSource.close()
   568→          eventSourceRef.current = null
   569→        }
   570→      }
   571→
   572→      eventSource.onerror = () => {
   573→        setSimplifyError('Connection lost. Please try again.')
   574→        setSimplifyStatus('error')
   575→        eventSource.close()
   576→        eventSourceRef.current = null
   577→      }
   578→    } catch (err) {
   579→      setSimplifyError(err instanceof Error ? err.message : 'Failed to generate')
   580→      setSimplifyStatus('error')
   581→    }
   582→  }
