                    {getSaveStatusDisplay(quizSaveStatus)}
                  </div>
                  <div className="flex gap-3">
                    {!isQuizSubmitted && (
                      <button
                        className="px-4 py-2 bg-blue-600 text-white rounded hover:bg-blue-700 disabled:opacity-50"
                        onClick={handleSubmitQuiz}
                        disabled={quizSaveStatus === 'saving' || Object.keys(quizAnswers).filter(k => quizAnswers[k]?.trim()).length === 0}
                      >
                        Submit Quiz
                      </button>
                    )}
                    {isQuizSubmitted && !evaluation?.evaluated && (
                      <button
                        className="px-4 py-2 bg-green-600 text-white rounded hover:bg-green-700 disabled:opacity-50"
                        onClick={handleEvaluate}
                        disabled={isEvaluating}
                      >
                        {isEvaluating ? 'Evaluating...' : 'Get AI Feedback'}
                      </button>
                    )}
                  </div>
                </div>
              </>
            )}
          </div>
        )}

        {/* FEEDBACK */}
        {activeTab === 'feedback' && (
          <div>
            <h3 className="text-lg font-semibold mb-4">Feedback</h3>
            {!evaluation?.evaluated ? (
              <div className="text-center py-8 text-gray-500">Complete the quiz and get AI feedback first.</div>
            ) : (
              <div className="space-y-8">
                {/* Score Summary */}
                <div className="grid grid-cols-2 gap-4">
                  <div className="bg-blue-50 border border-blue-200 rounded-lg p-4 text-center">
                    <p className="text-3xl font-bold text-blue-600">{evaluation.recall?.score ?? 0}/5</p>
                    <p className="text-sm text-blue-800">Recall Score</p>
                  </div>
                  <div className="bg-green-50 border border-green-200 rounded-lg p-4 text-center">
                    <p className="text-3xl font-bold text-green-600">{evaluation.quiz?.totalScore ?? 0}/{questions.length}</p>
                    <p className="text-sm text-green-800">Quiz Score</p>
                  </div>
                </div>

                {/* 1. Recall Feedback */}
                {evaluation.recall?.feedback && (
                  <div className="border rounded-lg p-4">
                    <h4 className="font-semibold mb-3">Recall Feedback</h4>
                    <p className="text-gray-700 mb-4">{evaluation.recall.feedback.reasoning}</p>
                    <div className="space-y-2">
                      {evaluation.recall.feedback.points?.map((point, i) => (
                        <div key={i} className={`border-l-4 pl-3 py-1 ${point.correct ? 'border-green-400' : 'border-red-400'}`}>
                          <span className="font-medium">{point.label}</span>
                          <p className="text-sm text-gray-600">{point.accuracy}</p>
                        </div>
                      ))}
                    </div>
                  </div>
                )}

                {/* 2. Revision Feedback */}
                {evaluation.revision?.feedback && (
                  <div className="border rounded-lg p-4">
                    <h4 className="font-semibold mb-3">Revision Feedback</h4>
                    <p className="text-gray-700 mb-4">{evaluation.revision.feedback.reasoning}</p>
                    {evaluation.revision.feedback.selfAwareness && (
                      <div className="bg-amber-50 rounded p-3 text-sm">
                        <span className="font-medium text-amber-800">Self-awareness: </span>
                        <span className="text-gray-700">{evaluation.revision.feedback.selfAwareness}</span>
                      </div>
                    )}
                  </div>
                )}

                {/* 3. Quiz Question Feedback */}
                {evaluation.quiz?.answers && evaluation.quiz.answers.length > 0 && (
                  <div className="border rounded-lg p-4">
                    <h4 className="font-semibold mb-4">Quiz Question Feedback</h4>
                    <div className="space-y-6">
                      {evaluation.quiz.answers.map((answer, idx) => {
                        const question = questions.find(q => q.id === answer.questionId)
                        const hasErrors = answer.feedback?.errors && answer.feedback.errors.length > 0
                        const hasWritingNote = answer.feedback?.writingNote

                        // Skip questions with no feedback
                        if (!hasErrors && !hasWritingNote) return null

                        return (
                          <div key={answer.questionId} className="border-l-4 pl-4 border-gray-200">
                            <div className="flex items-start gap-2 mb-2">
                              <span className={`px-2 py-0.5 rounded text-xs font-medium ${
                                answer.score >= 1 ? 'bg-green-100 text-green-800' :
                                answer.score >= 0.5 ? 'bg-yellow-100 text-yellow-800' :
                                'bg-red-100 text-red-800'
                              }`}>
                                {answer.score}/1
                              </span>
                              <p className="font-medium text-sm">{question?.questionText || `Question ${idx + 1}`}</p>
                            </div>

                            {hasErrors && (
                              <div className="space-y-2 mt-2">
                                {answer.feedback.errors.map((error, ei) => (
                                  <div key={ei} className="bg-red-50 rounded p-3 text-sm">
                                    {error.quoted_text && (
                                      <p className="text-red-700 italic mb-1">"{error.quoted_text}"</p>
                                    )}
                                    <p className="font-medium text-red-800">{error.summary}</p>
                                    <p className="text-gray-700 mt-1">{error.feedback}</p>
                                  </div>
                                ))}
                              </div>
                            )}

                            {hasWritingNote && (
                              <div className="bg-blue-50 rounded p-3 text-sm mt-2">
                                <span className="font-medium text-blue-800">Writing note: </span>
                                <span className="text-gray-700">{answer.feedback.writingNote}</span>
                              </div>
                            )}
                          </div>
                        )
                      })}
                    </div>
                  </div>
                )}

                {/* 4. Thematic Insights */}
                {evaluation.quiz?.thematicInsights && (
                  <div className="border rounded-lg p-4">
                    <h4 className="font-semibold mb-3">Thematic Insights</h4>
                    <div className="space-y-4">
                      <div>
                        <span className="font-medium">Source Mastery:</span>
                        <p className="text-gray-600 text-sm">{evaluation.quiz.thematicInsights.source_mastery}</p>
                      </div>
                      <div>
                        <span className="font-medium">Reasoning:</span>
                        <p className="text-gray-600 text-sm">{evaluation.quiz.thematicInsights.reasoning_quality}</p>
                      </div>
                    </div>
                  </div>
                )}

                {/* 5. Tutor's Note */}
                {evaluation.quiz?.tutorNote && (
                  <div className="bg-indigo-50 border border-indigo-200 rounded-lg p-4">
                    <h4 className="font-semibold text-indigo-800 mb-3">Tutor's Note</h4>
                    <div className="text-gray-700 whitespace-pre-wrap">{evaluation.quiz.tutorNote}</div>
                  </div>
                )}

                <div className="bg-green-50 border border-green-200 rounded-lg p-6 text-center">
                  <h4 className="font-semibold text-green-800 mb-2">Section Complete!</h4>
                  <p className="text-green-700 text-sm">You've completed all phases for this section.</p>
                </div>
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  )
}

