const prisma = new PrismaClient()

async function main() {
  // Create test user
  const user = await prisma.user.upsert({
    where: { email: 'test@example.com' },
    update: {},
    create: {
      id: 'test-user-e2e',
      email: 'test@example.com',
      name: 'Test User',
      readingLevel: 'undergraduate',
    },
  })

  // Create test book
  const book = await prisma.book.upsert({
    where: { slug: 'wealth-of-nations' },
    update: {},
    create: {
      slug: 'wealth-of-nations',
      title: 'The Wealth of Nations',
      author: 'Adam Smith',
      category: 'Economics',
    },
  })

  // Create test section with realistic content
  await prisma.section.upsert({
    where: {
      bookId_sectionNumber: { bookId: book.id, sectionNumber: 1 },
    },
    update: {},
    create: {
      bookId: book.id,
      sectionNumber: 1,
      title: 'Of the Division of Labour',
      priority: 'must',
      location: 'Book I, Chapter I',
      startByte: 0,
      endByte: 10000,
      wordCount: 2500,
      sectionContent: `The greatest improvement in the productive powers of labour, and the greater part of the skill, dexterity, and judgment with which it is any where directed, or applied, seem to have been the effects of the division of labour.

The effects of the division of labour, in the general business of society, will be more easily understood, by considering in what manner it operates in some particular manufactures.

To take an example, therefore, from a very trifling manufacture; but one in which the division of labour has been very often taken notice of, the trade of the pin-maker; a workman not educated to this business (which the division of labour has rendered a distinct trade), nor acquainted with the use of the machinery employed in it (to the invention of which the same division of labour has probably given occasion), could scarce, perhaps, with his utmost industry, make one pin in a day, and certainly could not make twenty.

But in the way in which this business is now carried on, not only the whole work is a peculiar trade, but it is divided into a number of branches, of which the greater part are likewise peculiar trades. One man draws out the wire, another straights it, a third cuts it, a fourth points it, a fifth grinds it at the top for receiving the head.`,
      // Leave summaryContent and detailedSummaryContent null for tests
    },
  })

  console.log('Test database seeded successfully')
}

main()
  .catch((e) => {
    console.error(e)
    process.exit(1)
  })
  .finally(async () => {
    await prisma.$disconnect()
  })

