describe('POST /api/section/[id]/generate', () => {
  it('starts generation and streams progress events', async () => {
    // Call the generate endpoint
    const response = await fetch(`http://localhost:3000/api/section/${sectionId}/generate`, {
      method: 'POST'
    })

    expect(response.ok).toBe(true)
    expect(response.headers.get('content-type')).toContain('text/event-stream')

    // Read first few events to verify processing started
    // Don't wait for completion - generate takes 5+ minutes for summary + quiz
    const reader = response.body?.getReader()
    if (!reader) throw new Error('No response body')

    const decoder = new TextDecoder()
    const events: Record<string, unknown>[] = []

    // Read until we see "Generating summary..." (step 2) which confirms:
    // 1. Prerequisites check passed
    // 2. Section found
    // 3. SectionAttempt created/updated
    // 4. Summary generation started
    while (events.length < 5) {
      const { done, value } = await reader.read()
      if (done) break

      const text = decoder.decode(value)
      const lines = text.split('\n').filter(l => l.startsWith('data: '))
      for (const line of lines) {
        const event = JSON.parse(line.replace('data: ', ''))
        events.push(event)

        // Once we see summary generation started, we've validated enough
        if (event.step === 2 && event.message?.includes('summary')) {
          reader.cancel() // Stop reading, don't wait for completion
          break
        }
      }
    }

    // Verify we got progress events
    expect(events.length).toBeGreaterThanOrEqual(1)

    const firstEvent = events[0] as { step: number; totalSteps: number; status: string }
    expect(firstEvent.step).toBe(1)
    expect(firstEvent.totalSteps).toBe(5)
    expect(firstEvent.status).toBe('in_progress')

    // If we got step 2, verify it's the summary generation step
    const summaryEvent = events.find(e => (e as { step: number }).step === 2)
    if (summaryEvent) {
      expect((summaryEvent as { message: string }).message).toContain('summary')
    }
  }, 30000) // 30 second timeout - just needs to start processing
})

