'use client'

import { useState } from 'react'
import { useRouter } from 'next/navigation'

interface Section {
  id: string
  sectionNumber: number
  title: string
  wordCount: number
  hasContent: boolean
  isStarted: boolean
  isCompleted: boolean
  currentPhase: string | null
}

interface SectionListProps {
  sections: Section[]
  bookSlug: string
}

interface ProgressState {
  step: number
  totalSteps: number
  message: string
  status: 'in_progress' | 'complete' | 'error'
}

// Human-readable phase names
const PHASE_LABELS: Record<string, string> = {
  read: 'Reading',
  blind_recall: 'Blind Recall',
  summary: 'Summary',
  revision: 'Revision',
  quiz: 'Quiz',
  feedback: 'Feedback',
  completed: 'Completed',
}

export default function SectionList({ sections, bookSlug }: SectionListProps) {
  const router = useRouter()
  const [generatingId, setGeneratingId] = useState<string | null>(null)
  const [progress, setProgress] = useState<ProgressState | null>(null)
  const [error, setError] = useState<string | null>(null)

  async function handleGenerateAndStart(section: Section) {
    setGeneratingId(section.id)
    setProgress(null)
    setError(null)

    try {
      const res = await fetch(`/api/section/${section.id}/generate`, {
        method: 'POST',
      })

      if (!res.body) {
        throw new Error('No response body')
      }

      const reader = res.body.getReader()
      const decoder = new TextDecoder()
      let buffer = ''

      while (true) {
        const { done, value } = await reader.read()
        if (done) break

        buffer += decoder.decode(value, { stream: true })
        const lines = buffer.split('\n\n')
        buffer = lines.pop() || ''

        for (const line of lines) {
          if (line.startsWith('data: ')) {
            const data = JSON.parse(line.slice(6)) as ProgressState
            setProgress(data)

            if (data.status === 'complete') {
              router.push(`/book/${bookSlug}/section/${section.sectionNumber}`)
              return
            }

            if (data.status === 'error') {
              setError(data.message)
              setGeneratingId(null)
              setProgress(null)
              return
            }
          }
        }
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Network error')
      setGeneratingId(null)
      setProgress(null)
    }
  }

  function canStartSection(index: number): boolean {
    // First section is always startable
    if (index === 0) return true
    // Subsequent sections require previous section to be completed
    return sections[index - 1].isCompleted
  }

  return (
    <div>
      {error && (
        <div className="mb-4 p-3 bg-red-50 border border-red-200 text-red-700 rounded">
          {error}
        </div>
      )}

      <div className="space-y-3">
        {sections.map((section, index) => {
          const isLocked = !canStartSection(index)
          const isGenerating = generatingId === section.id

          // Determine status for indicator
          let indicatorClass = 'bg-gray-100 text-gray-400'
          let indicatorContent: React.ReactNode = section.sectionNumber

          if (section.isCompleted) {
            indicatorClass = 'bg-green-100 text-green-700'
            indicatorContent = '✓'
          } else if (section.isStarted) {
            indicatorClass = 'bg-blue-100 text-blue-700'
            indicatorContent = '→'
          }

          return (
            <div
              key={section.id}
              className={`border rounded-lg p-4 flex items-center justify-between ${
                isLocked ? 'bg-gray-50 opacity-60' : ''
              }`}
            >
              <div className="flex items-center gap-4">
                {/* Status indicator */}
                <div
                  className={`w-8 h-8 rounded-full flex items-center justify-center text-sm ${indicatorClass}`}
                >
                  {indicatorContent}
                </div>

                <div>
                  <div className="font-semibold">{section.title}</div>
                  <div className="text-sm text-gray-500">
                    {section.wordCount.toLocaleString()} words
                    {section.isCompleted && (
                      <span className="ml-2 text-green-600">• Completed</span>
                    )}
                    {section.isStarted && !section.isCompleted && section.currentPhase && (
                      <span className="ml-2 text-blue-600">
                        • {PHASE_LABELS[section.currentPhase] || section.currentPhase}
                      </span>
                    )}
                    {isLocked && (
                      <span className="ml-2 text-amber-600">• Complete previous section first</span>
                    )}
                  </div>
                </div>
              </div>

              <div className="flex items-center gap-3">
                {isGenerating && progress && (
                  <div className="text-sm text-gray-600 text-right">
                    <div className="flex items-center gap-2">
                      <div className="w-24 h-2 bg-gray-200 rounded-full overflow-hidden">
                        <div
                          className="h-full bg-blue-500 transition-all duration-300"
                          style={{ width: `${(progress.step / progress.totalSteps) * 100}%` }}
                        />
                      </div>
                      <span className="text-xs text-gray-400">
                        {progress.step}/{progress.totalSteps}
                      </span>
                    </div>
                    <div className="text-xs mt-1">{progress.message}</div>
                  </div>
                )}
                {section.isStarted ? (
                  <a
                    href={`/book/${bookSlug}/section/${section.sectionNumber}`}
                    className="px-4 py-2 border rounded hover:bg-gray-50"
                  >
                    {section.isCompleted ? 'Review' : 'Continue'}
                  </a>
                ) : (
                  <button
                    className={`px-4 py-2 border rounded ${
                      isLocked || isGenerating
                        ? 'bg-gray-100 text-gray-400 cursor-not-allowed'
                        : 'hover:bg-gray-50'
                    }`}
                    disabled={isLocked || isGenerating}
                    onClick={() => handleGenerateAndStart(section)}
                  >
                    {isGenerating ? 'Generating...' : 'Generate & Start'}
                  </button>
                )}
              </div>
            </div>
          )
        })}
      </div>

      <div className="mt-6 text-sm text-gray-500">
        {sections.filter((s) => s.isCompleted).length} of {sections.length} sections completed
      </div>
    </div>
  )
}

