import { prisma } from '@/lib/db'
import { getDefaultUser } from '@/lib/user'
import { PHASES } from '@/lib/constants'
import { NextResponse } from 'next/server'

/**
 * POST /api/section/[id]/complete
 * Mark a section as completed after viewing feedback
 */
export async function POST(_req: Request, { params }: { params: Promise<{ id: string }> }) {
  const { id } = await params

  try {
    const user = await getDefaultUser()

    // Get the section attempt
    const attempt = await prisma.sectionAttempt.findUnique({
      where: {
        userId_sectionId: {
          userId: user.id,
          sectionId: id,
        },
      },
    })

    if (!attempt) {
      return NextResponse.json({ error: 'Section attempt not found' }, { status: 404 })
    }

    // Only allow completing from feedback phase
    if (attempt.currentPhase !== PHASES.FEEDBACK) {
      return NextResponse.json(
        { error: `Cannot complete from ${attempt.currentPhase} phase. Must be in feedback phase.` },
        { status: 400 }
      )
    }

    // Update to completed
    await prisma.sectionAttempt.update({
      where: { id: attempt.id },
      data: {
        currentPhase: PHASES.COMPLETED,
        completedAt: new Date(),
      },
    })

    return NextResponse.json({ success: true, phase: PHASES.COMPLETED })
  } catch (err) {
    console.error('[Complete] Error:', err)
    return NextResponse.json(
      { error: err instanceof Error ? err.message : 'Failed to complete section' },
      { status: 500 }
    )
  }
}

