import { prisma } from '@/lib/db'
import { getDefaultUser } from '@/lib/user'
import Link from 'next/link'
import { notFound } from 'next/navigation'
import SectionTabs from './SectionTabs'
import { PHASES, Phase } from '@/lib/constants'

interface SectionPageProps {
  params: { slug: string; num: string }
}

export default async function SectionPage({ params }: SectionPageProps) {
  const sectionNumber = parseInt(params.num, 10)

  if (isNaN(sectionNumber)) {
    notFound()
  }

  const book = await prisma.book.findUnique({
    where: { slug: params.slug },
    include: {
      sections: {
        where: { sectionNumber },
        select: {
          id: true,
          title: true,
          location: true,
          wordCount: true,
          sectionContent: true,
          summaryContent: true,
        },
      },
    },
  })

  if (!book || book.sections.length === 0) {
    notFound()
  }

  const section = book.sections[0]

  // Get or create section attempt to track phase progression
  const user = await getDefaultUser()
  let sectionAttempt = await prisma.sectionAttempt.findUnique({
    where: {
      userId_sectionId: {
        userId: user.id,
        sectionId: section.id,
      },
    },
    select: {
      currentPhase: true,
      blindSubmittedAt: true,
      quizAttempt: {
        select: {
          submittedAt: true,
          evaluatedAt: true,
        },
      },
    },
  })

  // If no attempt exists, create one at READ phase
  if (!sectionAttempt) {
    sectionAttempt = await prisma.sectionAttempt.create({
      data: {
        userId: user.id,
        sectionId: section.id,
        currentPhase: PHASES.READ,
      },
      select: {
        currentPhase: true,
        blindSubmittedAt: true,
        quizAttempt: {
          select: {
            submittedAt: true,
            evaluatedAt: true,
          },
        },
      },
    })
  }

  const currentPhase = (sectionAttempt.currentPhase as Phase) || PHASES.READ

  return (
    <main className="min-h-screen p-8">
      <nav className="mb-6 text-sm">
        <Link href="/library" className="text-blue-600 hover:underline">← Library</Link>
        <span className="mx-2 text-gray-400">/</span>
        <Link href={`/book/${params.slug}`} className="text-blue-600 hover:underline">{book.title}</Link>
        <span className="mx-2 text-gray-400">/</span>
        <span className="text-gray-600">Section {sectionNumber}</span>
      </nav>

      <h1 className="text-2xl font-bold mb-2">{section.title}</h1>
      <p className="text-gray-500 text-sm mb-6">
        {section.location} • {section.wordCount.toLocaleString()} words
      </p>

      <SectionTabs
        sectionId={section.id}
        sectionContent={section.sectionContent ?? ''}
        summaryContent={section.summaryContent ?? ''}
        initialPhase={currentPhase}
      />
    </main>
  )
}

