'use client'

import { useState, useEffect, useRef, useCallback } from 'react'
import { useRouter } from 'next/navigation'
import { Phase, PHASES, canAccessPhase, getPhaseIndex } from '@/lib/constants'
import { QuickSummary } from '@/components/summary/QuickSummary'
import { LegacySummary } from '@/components/summary/LegacySummary'
import { parseSummaryJson, isJsonSummary } from '@/lib/prompts/summaryParser'

type Tab = 'read' | 'recall' | 'summary' | 'revision' | 'quiz' | 'feedback'

// Map tabs to phases
const TAB_TO_PHASE: Record<Tab, Phase> = {
  read: PHASES.READ,
  recall: PHASES.BLIND_RECALL,
  summary: PHASES.SUMMARY,
  revision: PHASES.REVISION,
  quiz: PHASES.QUIZ,
  feedback: PHASES.FEEDBACK,
}

interface SectionTabsProps {
  sectionId: string
  sectionContent: string
  summaryContent: string
  initialPhase: Phase
}

interface RecallAnswers {
  mainClaim: string
  keyMechanism: string
  example: string
  modernParallel: string
  uncertainty: string
}

interface Question {
  id: string
  questionType: 'mcq' | 'prose'
  questionSubtype: string
  questionText: string
  options: string[] | null
  orderIndex: number
  savedAnswer: string | null
  feedback: { errors: Array<{ quoted_text: string; summary: string; feedback: string }>; writingNote: string | null } | null
  score: number | null
}

interface EvaluationData {
  evaluated: boolean
  recall?: {
    score: number
    feedback: {
      points: Array<{ label: string; correct: boolean; accuracy: string; reasoning: string }>
      one_sentence_ok: boolean
      one_sentence_note: string
      reasoning: string
    }
  }
  revision?: {
    feedback: {
      reasoning: string
      selfAwareness?: string
    }
  }
  quiz?: {
    totalScore: number
    thematicInsights: {
      source_mastery: string
      reasoning_quality: string
      writing_craft: { precision: number; clarity: number; economy: number; suggestion: string }
    }
    tutorNote: string
    answers: Array<{
      questionId: string
      questionText: string
      userAnswer: string
      score: number
      feedback: { errors: Array<{ quoted_text: string; summary: string; feedback: string }>; writingNote: string | null } | null
    }>
  }
  missedPoints?: Array<{ label: string; feedback: string }>
}

type SaveStatus = 'idle' | 'saving' | 'saved' | 'error'
type ReadView = 'original' | 'simplified'
type SimplifyStatus = 'idle' | 'loading' | 'ready' | 'error'
type SummaryView = 'quick' | 'detailed'
type DetailedStatus = 'idle' | 'loading' | 'ready' | 'error'

const TABS: { id: Tab; label: string; phase: Phase }[] = [
  { id: 'read', label: 'READ', phase: PHASES.READ },
  { id: 'recall', label: 'RECALL', phase: PHASES.BLIND_RECALL },
  { id: 'summary', label: 'SUMMARY', phase: PHASES.SUMMARY },
  { id: 'revision', label: 'REVISION', phase: PHASES.REVISION },
  { id: 'quiz', label: 'QUIZ', phase: PHASES.QUIZ },
  { id: 'feedback', label: 'FEEDBACK', phase: PHASES.FEEDBACK },
]

const RECALL_PROMPTS = [
  { id: 'mainClaim' as const, title: '1. Main Claim', question: 'What was the core argument? Write it in your own words.', placeholder: 'The author argues that...' },
  { id: 'keyMechanism' as const, title: '2. Key Mechanism', question: 'What process or cause-effect relationship was described?', placeholder: 'This happens because... which leads to...' },
  { id: 'example' as const, title: '3. Example I Remember', question: 'What example stuck with you?', placeholder: 'The author illustrated this with...' },
  { id: 'modernParallel' as const, title: '4. Modern Parallel', question: 'What connection to today came to mind while reading?', placeholder: 'This reminds me of how today...' },
  { id: 'uncertainty' as const, title: '5. Uncertainty', question: 'What am I unsure about or confused by?', placeholder: "I'm not sure about... or I wonder if..." },
]

const REVISION_PROMPTS = [
  { id: 'forgottenPoints' as const, title: '1. Forgotten Points', question: 'What key points did you forget?', placeholder: 'I forgot to mention...' },
  { id: 'misremembered' as const, title: '2. Misremembered Concepts', question: 'Were there concepts you misremembered?', placeholder: 'I thought... but actually...' },
  { id: 'missedExamples' as const, title: '3. Missed Examples', question: 'Which examples did you miss?', placeholder: 'The author also mentioned...' },
]

type RevisionAnswers = { forgottenPoints: string; misremembered: string; missedExamples: string }
const EMPTY_REVISION_ANSWERS: RevisionAnswers = { forgottenPoints: '', misremembered: '', missedExamples: '' }

const EMPTY_ANSWERS: RecallAnswers = { mainClaim: '', keyMechanism: '', example: '', modernParallel: '', uncertainty: '' }
const AUTOSAVE_DELAY_MS = 1500

export default function SectionTabs({ sectionId, sectionContent, summaryContent, initialPhase }: SectionTabsProps) {
  const router = useRouter()

  // Phase state - determines which tabs are accessible
  const [currentPhase, setCurrentPhase] = useState<Phase>(initialPhase)
  const [activeTab, setActiveTab] = useState<Tab>(getInitialTab(initialPhase))

  // Recall state
  const [recallAnswers, setRecallAnswers] = useState<RecallAnswers>(EMPTY_ANSWERS)
  const [recallSaveStatus, setRecallSaveStatus] = useState<SaveStatus>('idle')
  const [isRecallSubmitted, setIsRecallSubmitted] = useState(false)
  const [isRecallLoading, setIsRecallLoading] = useState(true)

  // Revision state
  const [revisionAnswers, setRevisionAnswers] = useState<RevisionAnswers>(EMPTY_REVISION_ANSWERS)
  const [revisionSaveStatus, setRevisionSaveStatus] = useState<SaveStatus>('idle')
  const [isRevisionSubmitted, setIsRevisionSubmitted] = useState(false)
  const [isRevisionLoading, setIsRevisionLoading] = useState(true)

  // Quiz state
  const [questions, setQuestions] = useState<Question[]>([])
  const [quizAnswers, setQuizAnswers] = useState<Record<string, string>>({})
  const [quizSaveStatus, setQuizSaveStatus] = useState<SaveStatus>('idle')
  const [isQuizSubmitted, setIsQuizSubmitted] = useState(false)
  const [isQuizLoading, setIsQuizLoading] = useState(true)

  // Evaluation state
  const [evaluation, setEvaluation] = useState<EvaluationData | null>(null)
  const [isEvaluating, setIsEvaluating] = useState(false)

  // Read view state
  const [readView, setReadView] = useState<ReadView>('original')
  const [simplifyStatus, setSimplifyStatus] = useState<SimplifyStatus>('idle')
  const [simplifiedContent, setSimplifiedContent] = useState<string>('')
  const [simplifiedParagraphs, setSimplifiedParagraphs] = useState<string[]>([])
  const [totalParagraphs, setTotalParagraphs] = useState(0)
  const [readingLevel, setReadingLevel] = useState<string>('undergraduate')
  const [simplifyError, setSimplifyError] = useState<string | null>(null)

  // Summary view state
  const [summaryView, setSummaryView] = useState<SummaryView>('quick')
  const [detailedStatus, setDetailedStatus] = useState<DetailedStatus>('idle')
  const [detailedContent, setDetailedContent] = useState<string>('')
  const [detailedParagraphs, setDetailedParagraphs] = useState<string[]>([])
  const [detailedTotal, setDetailedTotal] = useState(0)
  const [detailedError, setDetailedError] = useState<string | null>(null)
  const detailedAbortControllerRef = useRef<AbortController | null>(null)
  // Legacy ref name kept for compatibility with cleanup code
  const detailedEventSourceRef = useRef<{ close: () => void } | null>(null)

  // Ref for EventSource cleanup
  const eventSourceRef = useRef<EventSource | null>(null)

  // Refs
  const recallSaveTimerRef = useRef<NodeJS.Timeout | null>(null)
  const revisionSaveTimerRef = useRef<NodeJS.Timeout | null>(null)
  const quizSaveTimerRef = useRef<NodeJS.Timeout | null>(null)
  const recallInitialLoadRef = useRef(true)
  const revisionInitialLoadRef = useRef(true)
  const quizInitialLoadRef = useRef(true)

  function getInitialTab(phase: Phase): Tab {
    const phaseToTab: Record<Phase, Tab> = {
      [PHASES.READ]: 'read',
      [PHASES.BLIND_RECALL]: 'recall',
      [PHASES.SUMMARY]: 'summary',
      [PHASES.REVISION]: 'revision',
      [PHASES.QUIZ]: 'quiz',
      [PHASES.FEEDBACK]: 'feedback',
      [PHASES.COMPLETED]: 'feedback',
    }
    return phaseToTab[phase] || 'read'
  }

  function isTabAccessible(tab: Tab): boolean {
    const tabPhase = TAB_TO_PHASE[tab]
    return canAccessPhase(currentPhase, tabPhase)
  }

  function handleTabClick(tab: Tab) {
    if (!isTabAccessible(tab)) return
    setActiveTab(tab)
  }

  // Load recall answers
  useEffect(() => {
    async function loadRecall() {
      try {
        const res = await fetch(`/api/section/${sectionId}/recall`)
        const json = await res.json()
        if (json.success && json.data.answers) {
          setRecallAnswers(json.data.answers)
          setIsRecallSubmitted(json.data.submitted)
        }
      } catch (err) {
        console.error('Failed to load recall:', err)
      } finally {
        setIsRecallLoading(false)
        setTimeout(() => { recallInitialLoadRef.current = false }, 100)
      }
    }
    loadRecall()
  }, [sectionId])

  // Load revision answers
  useEffect(() => {
    async function loadRevision() {
      try {
        const res = await fetch(`/api/section/${sectionId}/revision`)
        const json = await res.json()
        if (json.success && json.data.answers) {
          setRevisionAnswers(json.data.answers)
          setIsRevisionSubmitted(json.data.submitted)
        }
      } catch (err) {
        console.error('Failed to load revision:', err)
      } finally {
        setIsRevisionLoading(false)
        setTimeout(() => { revisionInitialLoadRef.current = false }, 100)
      }
    }
    loadRevision()
  }, [sectionId])

  // Load quiz
  useEffect(() => {
    async function loadQuiz() {
      try {
        const res = await fetch(`/api/section/${sectionId}/quiz`)
        const json = await res.json()
        if (json.success) {
          setQuestions(json.data.questions)
          setIsQuizSubmitted(json.data.submitted)
          const savedAnswers: Record<string, string> = {}
          json.data.questions.forEach((q: Question) => {
            if (q.savedAnswer) savedAnswers[q.id] = q.savedAnswer
          })
          setQuizAnswers(savedAnswers)
        }
      } catch (err) {
        console.error('Failed to load quiz:', err)
      } finally {
        setIsQuizLoading(false)
        setTimeout(() => { quizInitialLoadRef.current = false }, 100)
      }
    }
    loadQuiz()
  }, [sectionId])

  // Load evaluation
  useEffect(() => {
    async function loadEvaluation() {
      try {
        const res = await fetch(`/api/section/${sectionId}/evaluate`)
        const json = await res.json()
        if (json.success && json.data.evaluated) {
          setEvaluation(json.data)
          if (json.data.phase) setCurrentPhase(json.data.phase as Phase)
        }
      } catch (err) {
        console.error('Failed to load evaluation:', err)
      }
    }
    loadEvaluation()
  }, [sectionId])

  // Recall autosave
  const saveRecall = useCallback(async (answers: RecallAnswers, submit = false) => {
    setRecallSaveStatus('saving')
    try {
      const res = await fetch(`/api/section/${sectionId}/recall`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ answers, submit }),
      })
      const json = await res.json()
      if (json.success) {
        setRecallSaveStatus('saved')
        if (submit) {
          setIsRecallSubmitted(true)
          setCurrentPhase(PHASES.SUMMARY)
          setActiveTab('summary')
          router.refresh()
        }
        setTimeout(() => setRecallSaveStatus('idle'), 2000)
      } else {
        setRecallSaveStatus('error')
      }
    } catch {
      setRecallSaveStatus('error')
    }
  }, [sectionId, router])

  useEffect(() => {
    if (recallInitialLoadRef.current || isRecallSubmitted) return
    if (recallSaveTimerRef.current) clearTimeout(recallSaveTimerRef.current)
    const hasContent = Object.values(recallAnswers).some((v) => v.trim())
    if (!hasContent) return
    recallSaveTimerRef.current = setTimeout(() => saveRecall(recallAnswers), AUTOSAVE_DELAY_MS)
    return () => { if (recallSaveTimerRef.current) clearTimeout(recallSaveTimerRef.current) }
  }, [recallAnswers, saveRecall, isRecallSubmitted])

  // Revision autosave
  const saveRevision = useCallback(async (answers: RevisionAnswers, submit = false) => {
    setRevisionSaveStatus('saving')
    try {
      const res = await fetch(`/api/section/${sectionId}/revision`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ answers, submit }),
      })
      const json = await res.json()
      if (json.success) {
        setRevisionSaveStatus('saved')
        if (submit) {
          setIsRevisionSubmitted(true)
          setCurrentPhase(PHASES.QUIZ)
          setActiveTab('quiz')
          router.refresh()
        }
        setTimeout(() => setRevisionSaveStatus('idle'), 2000)
      } else {
        setRevisionSaveStatus('error')
      }
    } catch {
      setRevisionSaveStatus('error')
    }
  }, [sectionId, router])

  useEffect(() => {
    if (revisionInitialLoadRef.current || isRevisionSubmitted) return
    if (revisionSaveTimerRef.current) clearTimeout(revisionSaveTimerRef.current)
    const hasContent = Object.values(revisionAnswers).some((v) => v.trim())
    if (!hasContent) return
    revisionSaveTimerRef.current = setTimeout(() => saveRevision(revisionAnswers), AUTOSAVE_DELAY_MS)
    return () => { if (revisionSaveTimerRef.current) clearTimeout(revisionSaveTimerRef.current) }
  }, [revisionAnswers, saveRevision, isRevisionSubmitted])

  // Quiz autosave
  const saveQuiz = useCallback(async (answers: Record<string, string>, submit = false) => {
    setQuizSaveStatus('saving')
    try {
      const answersArray = Object.entries(answers).map(([questionId, answer]) => ({ questionId, answer }))
      const res = await fetch(`/api/section/${sectionId}/quiz`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ answers: answersArray, submit }),
      })
      const json = await res.json()
      if (json.success) {
        setQuizSaveStatus('saved')
        if (submit) setIsQuizSubmitted(true)
        setTimeout(() => setQuizSaveStatus('idle'), 2000)
      } else {
        setQuizSaveStatus('error')
      }
    } catch {
      setQuizSaveStatus('error')
    }
  }, [sectionId])

  useEffect(() => {
    if (quizInitialLoadRef.current || isQuizSubmitted) return
    if (quizSaveTimerRef.current) clearTimeout(quizSaveTimerRef.current)
    const hasContent = Object.values(quizAnswers).some((v) => v?.trim())
    if (!hasContent) return
    quizSaveTimerRef.current = setTimeout(() => saveQuiz(quizAnswers), AUTOSAVE_DELAY_MS)
    return () => { if (quizSaveTimerRef.current) clearTimeout(quizSaveTimerRef.current) }
  }, [quizAnswers, saveQuiz, isQuizSubmitted])

  // Load user reading level preference
  useEffect(() => {
    async function loadReadingLevel() {
      try {
        const res = await fetch('/api/user/preferences')
        const json = await res.json()
        if (json.success) {
          setReadingLevel(json.data.readingLevel)
        }
      } catch (err) {
        console.error('Failed to load reading level:', err)
      }
    }
    loadReadingLevel()
  }, [])

  // Cleanup EventSource and AbortController on unmount
  useEffect(() => {
    return () => {
      if (eventSourceRef.current) {
        eventSourceRef.current.close()
      }
      // Abort any in-flight detailed summary request
      if (detailedAbortControllerRef.current) {
        detailedAbortControllerRef.current.abort()
        detailedAbortControllerRef.current = null
      }
    }
  }, [])

  // Phase advancement handlers
  function handleFinishReading() {
    if (getPhaseIndex(currentPhase) < getPhaseIndex(PHASES.BLIND_RECALL)) {
      setCurrentPhase(PHASES.BLIND_RECALL)
    }
    setActiveTab('recall')
  }

  function handleSubmitRecall() {
    if (recallSaveTimerRef.current) clearTimeout(recallSaveTimerRef.current)
    saveRecall(recallAnswers, true)
  }

  function handleFinishSummary() {
    if (getPhaseIndex(currentPhase) < getPhaseIndex(PHASES.REVISION)) {
      setCurrentPhase(PHASES.REVISION)
    }
    setActiveTab('revision')
  }

  async function handleDetailedClick() {
    // When toggling BACK to Quick Review, close any active SSE connection
    // This prevents background updates and wasted resources
    if (summaryView === 'detailed') {
      if (detailedEventSourceRef.current) {
        detailedEventSourceRef.current.close()
        detailedEventSourceRef.current = null
      }
      setSummaryView('quick')
      return
    }

    // Cleanup any existing EventSource before starting new one
    if (detailedEventSourceRef.current) {
      detailedEventSourceRef.current.close()
      detailedEventSourceRef.current = null
    }

    setSummaryView('detailed')
    setDetailedError(null)
    setDetailedContent('')
    setDetailedParagraphs([])
    setDetailedTotal(0)
    setDetailedStatus('loading')

    try {
      // Use POST with fetch (not EventSource) because:
      // 1. EventSource only supports GET
      // 2. This endpoint triggers AI generation (should be POST)
      // 3. We need AbortController support for cleanup
      const abortController = new AbortController()
      detailedAbortControllerRef.current = abortController

      const response = await fetch(`/api/section/${sectionId}/detailed/stream`, {
        method: 'POST',
        signal: abortController.signal,
      })

      if (!response.ok) {
        throw new Error(`HTTP ${response.status}`)
      }

      const reader = response.body?.getReader()
      if (!reader) throw new Error('No response body')

      const decoder = new TextDecoder()

      while (true) {
        const { done, value } = await reader.read()
        if (done) break

        const text = decoder.decode(value)
        const lines = text.split('\n').filter(l => l.startsWith('data: '))

        for (const line of lines) {
          const data = JSON.parse(line.replace('data: ', ''))

          if (data.error) {
            setDetailedError(data.error)
            setDetailedStatus('error')
            return
          }

          if (data.cached) {
            setDetailedContent(data.text)
            setDetailedStatus('ready')
            return
          }

          // Use != null to handle total: 0 edge case
          if (data.total != null) {
            setDetailedTotal(data.total)
          }

          if (data.paragraph !== undefined && data.text) {
            setDetailedParagraphs((prev) => {
              const updated = [...prev]
              updated[data.paragraph] = data.text
              return updated
            })
          }

          if (data.done) {
            setDetailedStatus('ready')
          }
        }
      }
    } catch (err) {
      // AbortError means user navigated away - not a real error
      if (err instanceof Error && err.name === 'AbortError') {
        console.log('[Detailed] Request aborted by user')
        return
      }
      setDetailedError(err instanceof Error ? err.message : 'Failed to load')
      setDetailedStatus('error')
    } finally {
      detailedAbortControllerRef.current = null
    }
  }

